function _showLoadingSpinner(show) {
  const app = document.getElementById('app');
  let spinner = document.getElementById('_db_spinner');
  if (show && !spinner) {
    spinner = document.createElement('div');
    spinner.id = '_db_spinner';
    spinner.style.cssText = 'position:fixed;inset:0;background:rgba(255,255,255,.85);z-index:9999;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px';
    spinner.innerHTML = '<div style="width:36px;height:36px;border:3px solid #C9A84C;border-top-color:transparent;border-radius:50%;animation:spin 0.7s linear infinite"></div><div style="font-size:13px;color:#374151;font-weight:500">Loading data…</div>';
    if (!document.querySelector('#_spin_style')) {
      const s = document.createElement('style');
      s.id = '_spin_style';
      s.textContent = '@keyframes spin{to{transform:rotate(360deg)}}';
      document.head.appendChild(s);
    }
    document.body.appendChild(spinner);
  } else if (!show && spinner) {
    spinner.remove();
  }
}

